1726	+/// transport boundary is faked.
1727	+///
1728	+/// A queued SSE response is delivered as the exact [chunks] given, each
1729	+/// its own separate stream emission (never pre-joined into one string) —
1730	+/// this is what proves `ChatRemoteDataSource.sendMessage`'s own
1731	+/// `\n\n`-boundary buffering really works across genuine network chunk
1732	+/// boundaries, not just against a single already-complete event.
1733	+class _FakeHttpClientAdapter implements HttpClientAdapter {
1734	+  final List<RequestOptions> requests = [];
1735	+  final List<ResponseBody Function()> _queue = [];
1736	+
1737	+  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
1738	+    _queue.add(
1739	+      () => ResponseBody.fromString(
1740	+        jsonEncode(body),
1741	+        statusCode,
1742	+        headers: {
1743	+          Headers.contentTypeHeader: [Headers.jsonContentType],
1744	+        },
1745	+      ),
1746	+    );
1747	+  }
1748	+
1749	+  void queueErrorResponse(String code, String message, {int statusCode = 503}) {
1750	+    queueJsonResponse(statusCode, {
1751	+      'code': code,
1752	+      'message': message,
1753	+      'retryable': true,
1754	+    });
1755	+  }
1756	+
1757	+  void queueSseResponse(List<String> chunks, {int statusCode = 200}) {
1758	+    _queue.add(
1759	+      () => ResponseBody(
1760	+        Stream.fromIterable(
1761	+          chunks.map((chunk) => Uint8List.fromList(utf8.encode(chunk))),
1762	+        ),
1763	+        statusCode,
1764	+        headers: {
1765	+          Headers.contentTypeHeader: ['text/event-stream'],
1766	+        },
1767	+      ),
1768	+    );
1769	+  }
1770	+
1771	+  @override
1772	+  Future<ResponseBody> fetch(
1773	+    RequestOptions options,
1774	+    Stream<Uint8List>? requestStream,
1775	+    Future<void>? cancelFuture,
1776	+  ) async {
1777	+    requests.add(options);
1778	+    if (_queue.isEmpty) {
1779	+      throw StateError(
1780	+        'No queued response for ${options.method} ${options.path}',
1781	+      );
1782	+    }
1783	+    return _queue.removeAt(0)();
1784	+  }
